import{_ as t,o as n,c as a,a0 as i}from"./chunks/framework.DYS8d9tm.js";const m=JSON.parse('{"title":"✨ WealthFam Features","description":"","frontmatter":{},"headers":[],"relativePath":"user/features.md","filePath":"user/features.md"}'),o={name:"user/features.md"};function r(s,e,l,c,d,g){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="✨-wealthfam-features" tabindex="-1">✨ WealthFam Features <a class="header-anchor" href="#✨-wealthfam-features" aria-label="Permalink to &quot;✨ WealthFam Features&quot;">​</a></h1><p>A comprehensive overview of what you can achieve with WealthFam.</p><h2 id="📊-holistic-dashboard-unified-cash-flow-math" tabindex="-1">📊 Holistic Dashboard &amp; Unified Cash-Flow Math <a class="header-anchor" href="#📊-holistic-dashboard-unified-cash-flow-math" aria-label="Permalink to &quot;📊 Holistic Dashboard &amp; Unified Cash-Flow Math&quot;">​</a></h2><ul><li><strong>Real-time Balance Sheet</strong>: Instantly view Net Worth, Liquidity, and Debt.</li><li><strong>Spending Velocity</strong>: Sparklines and hierarchical category breakdowns powered by relational <code>category_id</code> foreign keys.</li><li><strong>Unified Income, Expense &amp; Investment Alignment</strong>: Across Web and Mobile, Operating Income strictly reflects <code>&#39;income&#39;</code> categories, Living Expenses automatically net positive <code>&#39;expense&#39;</code> refunds against gross debits, and internal transfers (<code>is_transfer = True</code>, <code>exclude_from_reports = True</code>) are universally excluded from analytics.</li><li><strong>Full-Screen Interactive Spending Map (<code>/spending-map</code> &amp; Mobile Full Map)</strong>: Dedicated geo-intelligence screen with spend-tiered cluster-zoom (<code>N · ₹sum</code>), Hybrid/Pins/Heat layer switching, theme-aware basemaps, privacy-first location &amp; merchant search (local matches + OpenStreetMap Nominatim place search), pin filtering (date, category, account, expense group, amount range), and live viewport spend summaries—backed by RFC 0001 encrypted coordinates.</li></ul><h2 id="📈-mutual-funds-tracking-intelligence-suite" tabindex="-1">📈 Mutual Funds Tracking &amp; Intelligence Suite <a class="header-anchor" href="#📈-mutual-funds-tracking-intelligence-suite" aria-label="Permalink to &quot;📈 Mutual Funds Tracking &amp; Intelligence Suite&quot;">​</a></h2><ul><li><strong>XIRR &amp; Performance</strong>: Automated tracking with Decimal precision.</li><li><strong>Unified Portfolio</strong>: Manage multiple folios across CAMS, KFintech, and CDSL/NSDL CAS statements.</li><li><strong>FIFO Tax Optimization &amp; Harvesting</strong>: Real-time ₹1.25L annual LTCG exemption tracking (Finance Act 2024), FIFO lot decomposition, unrealized gains classification (LTCG vs STCG), and near-LTCG qualification alerts (315–365 days).</li><li><strong>Portfolio Overlap &amp; Entity Concentration</strong>: Pairwise fund overlap matrix $\\sum \\min(w_A, w_B)$ and aggregate company holding concentration with risk severity alerts and diversity scoring.</li><li><strong>Sectoral Heatmap &amp; Pareto Exposure</strong>: Exposure breakdown across 12 standard sectors, Large/Mid/Small cap allocation, and key constituent stock drilldowns.</li><li><strong>SIP Intelligence &amp; 30-Day Liquidity Calendar</strong>: Automated detection of recurring SIPs, verified vs auto-detected mandate management with one-tap toggle, cash-flow liquidity matching against primary bank balances, and 5/10/15-year compounding step-up simulator.</li><li><strong>Peer Benchmarking &amp; Risk-Return Quadrant Matrix</strong>: Cross-sectional Alpha ($\\alpha$) vs Beta ($\\beta$) quadrant matrix chart, Sharpe ratio analysis against category TRI benchmarks, and Glassmorphic AI Advisor executive intelligence reports.</li><li><strong>Family Member Filter Parity</strong>: Seamless toggling between individual family member portfolios and consolidated household intelligence views.</li></ul><h2 id="🧠-ai-intelligence" tabindex="-1">🧠 AI Intelligence <a class="header-anchor" href="#🧠-ai-intelligence" aria-label="Permalink to &quot;🧠 AI Intelligence&quot;">​</a></h2><ul><li><strong>Smart Categorization</strong>: Automated classification.</li><li><strong>Deep Insights</strong>: Gemini-powered analytics.</li></ul><h2 id="🕒-subscription-management" tabindex="-1">🕒 Subscription Management <a class="header-anchor" href="#🕒-subscription-management" aria-label="Permalink to &quot;🕒 Subscription Management&quot;">​</a></h2><ul><li><strong>Recurring Transactions</strong>: Factor billing into liquidity.</li></ul><h2 id="🏦-specialized-financial-instruments" tabindex="-1">🏦 Specialized Financial Instruments <a class="header-anchor" href="#🏦-specialized-financial-instruments" aria-label="Permalink to &quot;🏦 Specialized Financial Instruments&quot;">​</a></h2><ul><li><strong>Fixed &amp; Recurring Deposits</strong>: Track deposits with automated compounding interest simulation, tenure timelines, and maturity projections.</li><li><strong>Provident Funds (EPF / PPF / NPS)</strong>: Tripartite EPF split (Employee, Employer, Pension), annual statutory interest estimation, and post-tax statutory deposit tracking (₹1.5L annual ceiling).</li><li><strong>Credit Cards</strong>: Track statement cycles (<code>current_unbilled</code>, <code>last_statement</code>), utilization health, bill due dates, and minimum payments due.</li><li><strong>Loans &amp; EMIs</strong>: Manage lenders, track loan account numbers, and monitor EMI debits.</li></ul><h2 id="🔄-cross-account-transfers-pairing" tabindex="-1">🔄 Cross-Account Transfers &amp; Pairing <a class="header-anchor" href="#🔄-cross-account-transfers-pairing" aria-label="Permalink to &quot;🔄 Cross-Account Transfers &amp; Pairing&quot;">​</a></h2><ul><li><strong>Automated Match Detection</strong>: Smart heuristic engine detects funds moving between your own accounts (e.g. Bank to Card bill payment or savings transfers).</li><li><strong>Zero Expense Inflation</strong>: Paired transfers are automatically excluded from spending analytics, keeping cash flow reports accurate.</li><li><strong>1-Click Counterpart Leg Generation</strong>: Auto-generate missing receiving credits directly with adjustable amounts for cashback or payment discounts.</li></ul><h2 id="🔐-zero-knowledge-privacy-enterprise-encryption" tabindex="-1">🔐 Zero-Knowledge Privacy &amp; Enterprise Encryption <a class="header-anchor" href="#🔐-zero-knowledge-privacy-enterprise-encryption" aria-label="Permalink to &quot;🔐 Zero-Knowledge Privacy &amp; Enterprise Encryption&quot;">​</a></h2><ul><li><strong>Field-Level Database Encryption (RFC 0001)</strong>: User full names, email addresses, phone numbers, PAN numbers, account numbers, email IMAP passwords, and GPS transaction coordinates are encrypted at the database level with AES-256-GCM.</li><li><strong>Encrypted Document Vault</strong>: All physical documents, tax filings, statement PDFs, and receipt thumbnails on disk (<code>/data/vault/</code>) are chunk-encrypted using streaming AES-256-GCM with magic header <code>b&quot;WFENC\\x01&quot;</code>. Stored files cannot be opened or read outside of authorized tenant sessions.</li><li><strong>Blind Index Lookups</strong>: Exact-match searches (such as logging in with your email or linking accounts) operate via deterministic HMAC-SHA256 blind indexing, preventing DB dumps from exposing plaintext.</li><li><strong>Zero-Retention Ingestion</strong>: Raw email and SMS bodies are processed statelessly in-memory and discarded immediately after extraction, eliminating long-term raw communication storage.</li><li><strong>Consent-Driven Training Sharing</strong>: Users can voluntarily choose to share anonymized transaction patterns for parser improvements; shared items undergo format-preserving structural sanitization before transmission.</li></ul><h2 id="📂-document-vault-attachments" tabindex="-1">📂 Document Vault &amp; Attachments <a class="header-anchor" href="#📂-document-vault-attachments" aria-label="Permalink to &quot;📂 Document Vault &amp; Attachments&quot;">​</a></h2><ul><li><strong>Persistent <code>/data/vault</code> Storage &amp; Self-Healing</strong>: Documents persist across container upgrades in <code>/data/vault</code> with automatic startup/runtime path self-healing and surviving earlier-version fallback resolution.</li><li><strong>Hierarchical Storage</strong>: Organize tax forms, receipts, statements, and investment documents in nested folders.</li><li><strong>Transaction Linking &amp; Lazy Previews</strong>: Attach receipts and invoices directly to transactions with in-app PDF and image previews, on-demand auto-unlocking of legacy encrypted statement PDFs, and lazy thumbnail generation without 404 console spam on locked PDFs.</li></ul><h2 id="📱-mobile-app-android" tabindex="-1">📱 Mobile App (Android) <a class="header-anchor" href="#📱-mobile-app-android" aria-label="Permalink to &quot;📱 Mobile App (Android)&quot;">​</a></h2><ul><li><strong>Real-time Ingestion</strong>: Automated SMS financial alert capture with high-accuracy GPS tagging.</li><li><strong>Document Scanner with Auto-Straightening</strong>: Integrated native document scanner featuring auto-edge detection, perspective straightening, shadow removal, and contrast enhancement to capture and attach crisp receipt documents directly to transactions and Vault folders.</li><li><strong>3-Way Transaction Classification</strong>: Manual transaction entry seamlessly classifies outflows as <code>Expense</code> or <code>Investment</code>, or inflows as <code>Income</code>, with category scoping tabs (<code>All</code>, <code>Expense</code>, <code>Income</code>, <code>Investment</code>).</li><li><strong>Unified Savings Rate &amp; 6-Month Trend Sparklines</strong>: Mobile dashboard features smooth Bézier sparklines for 6-month investment and spending trends, with real-time unified savings rate calculations strictly separating investments from operational living expenses.</li><li><strong>Attention &amp; Activity Hub</strong>: Two-tab command center with actionable pending items (unlocked statements, triage items, card dues) and a persistent, deduplicated notification activity stream synchronized with the database.</li><li><strong>Accessible Touch Target Compliance</strong>: Enforced $\\ge 48\\times 48\\text{ dp}$ primary touch targets and $\\ge 36\\text{ dp}$ inline actions for effortless single-handed mobile operation.</li><li><strong>Mobile Transfers Hub</strong>: Approve detected transfers in bulk and create counterpart legs on the go.</li><li><strong>Dedicated Instrument Views</strong>: Instant mobile access to Deposits, Provident Funds, and Credit Cards.</li><li><strong>Active Expense Group Assignment</strong>: Group assignment picker cleanly filters out archived groups while preserving historical assignments.</li><li><strong>Living vs Total Spend Alignment</strong>: Ledger spend headers explicitly reconcile operational living spending against investments and internal transfers with clear tooltip breakdowns.</li></ul><h2 id="🏦-bulk-statement-reconciliation-management" tabindex="-1">🏦 Bulk Statement Reconciliation &amp; Management <a class="header-anchor" href="#🏦-bulk-statement-reconciliation-management" aria-label="Permalink to &quot;🏦 Bulk Statement Reconciliation &amp; Management&quot;">​</a></h2><ul><li><strong>Attended Statements Hidden by Default</strong>: Attended statements are hidden by default across Web and Mobile to keep review queues clean and focused on action items. A 1-click <strong>Show Attended / Showing Attended</strong> toggle reveals both attended and unattended statements whenever audit is needed, with real-time selection auto-advance upon attending.</li><li><strong>Statement-Level Full CRUD</strong>: Upload or email-sync PDF statements, filter by status (<code>All</code>, <code>Parsed</code>, <code>Pending</code>, <code>Failed</code>) and filename, edit filename (synced with Vault), statement type, and linked account, and delete single or multiple statements with optional Vault PDF removal.</li><li><strong>Statement Ignore Rules</strong>: Block recurring promotional/non-statement email PDFs by sender, email subject, or filename keyword directly from the <strong>Statements</strong> view (via the <strong>Ignored Rules</strong> manager or single-statement 🚫 Ignore modal) as well as <strong>Settings → Ingestions</strong>, with bulk cleanup of existing matching <code>PENDING</code>/<code>FAILED</code> items while keeping <code>PARSED</code> history safe.</li><li><strong>Smart PDF &amp; CDSL eCAS Ingestion</strong>: Specialized extraction for bank statements, credit cards, and Consolidated Account Statements (CAMS, KFintech, CDSL <code>eCAS@cdslstatement.com</code>, NSDL), SHA-256 version deduplication preventing duplicate Vault versions on retries, and partial-unlock reprocess continuity when decryption succeeds ahead of parsing.</li><li><strong>Automated Rule Persistence</strong>: Generate classification rules directly from ingestion flows with PostgreSQL-safe JSON keyword queries.</li><li><strong>Bulk Triage &amp; Normalized Categories</strong>: Confirm hundreds of transactions in seconds with searchable category selection (<code>:teleport=&quot;true&quot;</code> to prevent container clipping) and leaf-category normalization.</li><li><strong>Pending Triage Auto-Promotion</strong>: Reconciling statement transactions automatically resolves matching pending triage items into official ledger records.</li><li><strong>Category Rules Review Prioritization</strong>: Rules matching pending triage items are automatically pinned to the top of the rules list with amber badges (<code>⚡ X in Review</code>) and quick-filter toggles.</li></ul><h2 id="⚡-global-attention-action-required-hub" tabindex="-1">⚡ Global Attention &amp; Action Required Hub <a class="header-anchor" href="#⚡-global-attention-action-required-hub" aria-label="Permalink to &quot;⚡ Global Attention &amp; Action Required Hub&quot;">​</a></h2><ul><li><strong>Unified Action Center</strong>: Top-bar unified Bell icon with pending badge count (<code>🔔 {N}</code>) on Web and dynamic &quot;Pending Actions&quot; row on Mobile aggregating all pending financial decisions into a single click-to-resolve queue.</li><li><strong>Statement Attendance Lifecycle</strong>: Explicitly mark parsed statements as &quot;Attended &amp; Closed&quot; or reopen them, with protective confirmation warnings when unreconciled transactions remain and auto-resetting upon reprocessing.</li><li><strong>Multi-Domain Intelligence</strong>: Automatically detects pending triage transactions, suggested cross-account transfers, overdue or approaching credit card bills, category budget breaches, loan EMI deadlines, recurring subscription patterns, account low-balance/overdraft states, and stale mutual fund CAS statements.</li><li><strong>Child Account Shielding</strong>: Automatic role-based security strictly hides household debts, loans, statements, and financial accounts from child members while preserving their personal triage queue.</li><li><strong>Sub-15ms Single-Pass Aggregation</strong>: High-performance conditional aggregation engine ensuring instant UI responsiveness without background polling load spikes.</li></ul><h2 id="💾-portable-system-backup-restore-wfam" tabindex="-1">💾 Portable System Backup &amp; Restore (<code>.wfam</code>) <a class="header-anchor" href="#💾-portable-system-backup-restore-wfam" aria-label="Permalink to &quot;💾 Portable System Backup &amp; Restore (`.wfam`)&quot;">​</a></h2><ul><li><strong>Complete Server-Independent Export</strong>: Export your entire family workspace—accounts, transactions, categories, rules, budgets, loans, credit cards, FDs, PFs, mutual funds, goals, statements, Document Vault files, email configs, and settings—into a single <code>.wfam</code> file under <strong>Settings → Backup &amp; Restore</strong>.</li><li><strong>Custom Passphrase Encryption</strong>: Server encryption keys and database UUIDs are stripped for cross-server portability, then wrapped by default in a streaming 64KB chunked <strong>AES-256-GCM + PBKDF2-SHA256</strong> container locked with your own passphrase.</li><li><strong>Email-Verified, Priority-Preserving Merge Restore</strong>: Restore months later or on a brand-new server using the owner or any family member&#39;s email; existing data on the new server is never wiped and keeps highest priority while backup records merge in with freshly generated IDs.</li><li><strong>Role-Protected Access</strong>: Available to <code>OWNER</code> and <code>ADULT</code> family members; <code>CHILD</code> and <code>GUEST</code> accounts are strictly restricted.</li></ul>',26)])])}const p=t(o,[["render",r]]);export{m as __pageData,p as default};
